tool_input.command:
mkdir -p "$TMPDIR/scratch" && cat > "$TMPDIR/scratch/Scratch.java" <<'EOF'
import org.apache.commons.lang3.ClassUtils;
public class Scratch {
    interface I1 {}
    interface I2 extends I1 {}
    static class GP implements I1 {}
    static class P extends GP implements I2 {}
    static class C extends P {}
    public static void main(String[] a) {
        for (Class<?> c : ClassUtils.hierarchy(C.class, ClassUtils.Interfaces.INCLUDE)) {
            System.out.println(c.getSimpleName());
        }
        System.out.println("---superclasses---");
        for (Class<?> c : ClassUtils.getAllSuperclasses(C.class)) System.out.println(c.getSimpleName());
        System.out.println("---interfaces---");
        for (Class<?> c : ClassUtils.getAllInterfaces(C.class)) System.out.println(c.getSimpleName());
    }
}
EOF
javac -cp target/classes -d "$TMPDIR/scratch" "$TMPDIR/scratch/Scratch.java" && java -cp "target/classes:$TMPDIR/scratch" Scratch
